import { forwardRef, useImperativeHandle, useRef, useMemo } from "react";
import Select from "react-select";
import InfoIcon from "../Tooltip/InfoIcon";
const OptionSelection = forwardRef(
  (
    {
      label,
      customClass,
      selectedOption,
      setSelectedOption,
      options,
      placeholder = "",
      disable,
      customDropDown,
      isClearable = false,
      dropDownRef,
      infoIconBody = "",
      iconPlacement = "top",
      textAlignment = "left",
      important = false,
    },
    ref
  ) => {
    const classNamePrefix = `DepartmentCompStyle-${label.replace(/\s+/g, "")}`;
  
  const innerRef = useRef(null); // will point to <select> or react-select instance
  const resolvedRef = dropDownRef ?? innerRef;

  // Expose focus/blur no matter what the inner control is
    useImperativeHandle(ref, () => ({
      focus: () => resolvedRef.current?.focus?.(),
      blur: () => resolvedRef.current?.blur?.(),
      get node() {
        return resolvedRef.current;
      },
    }));

    // Add placeholder as the first option
    const finalOptions = useMemo(() => {
      if(placeholder == "" || placeholder == null){
        return options || [];
      }
      const placeholderOption = { value: "", label: placeholder };
      return [placeholderOption, ...(options || [])];
    }, [placeholder, options]);

    // If no option is selected, select the placeholder option
    const finalSelectedOption = useMemo(() => {      
      if (!selectedOption) {        
        return { value: "", label: placeholder };
      }
      return selectedOption;
    }, [placeholder, selectedOption]);

    return (
      <div className={`dropdown-wrapper ${classNamePrefix} ${customClass}`}>
        <Select
          classNamePrefix={`${customDropDown} DepartmentCompStyle`}
          value={finalSelectedOption}
          onChange={setSelectedOption}
          options={finalOptions}
          isClearable={isClearable}
          menuPortalTarget={document.body}
          isDisabled={disable == null ? false : disable}
          formatOptionLabel={(data, { inputValue }) => (
            <div style={{ fontSize: "14px" }}>{data.label}</div>
          )}
          menuPlacement="auto"
          ref={resolvedRef}
          styles={{
            menuPortal: (base) => ({ ...base, zIndex: 9999 }),
          container: (base) => ({ ...base, width: `${infoIconBody !== "" ? "calc(100% - 30px)" : "100%"}`,textAlign:`${textAlignment}` }),          
control: (base) => ({
              ...base,
              backgroundColor: important ? "rgb(255, 255, 232)" : base.backgroundColor,
            }),        
          }}
          menuPosition="fixed"
        />
      {infoIconBody != "" && (
          <div className="infoIcon-OptionSelection-container">
            <InfoIcon body={infoIconBody} placement={iconPlacement} />
          </div>
        )}
        <div className="custom-label">{label}</div>
    </div>
  );
  }
);

export default OptionSelection;
