import { useEffect, useState, useRef } from "react";
import { Table } from "react-bootstrap";
import { motion } from "framer-motion";
import { toast } from "react-toastify";
import html2canvas from "html2canvas";
import MailPopup from "../Popup/MailPopup";
import apiService from "../../ApiService/apiService";
import { getTableDataByKey } from "../../IndexDbServices/indexDbServices";
import { MdInfoOutline } from "react-icons/md";
import CustomTooltip from "../Tooltip/CustomTooltip";
import { useGetTokenValue } from "../../CustomHooks/GetTokenValue";
import { isValid, format, parse } from "date-fns";
import { BsInfoCircleFill } from "react-icons/bs";
import InfoIcon from "../Tooltip/InfoIcon";
import { thousandformater } from "../../Utilities/thousandFormater";

export default function RecordGrid({
  allowExpandCollapse = false,
  tablebody,
  id,
  currentPage,
  setSelectedRecord,
  gridModel,
  csvName,
  rowsPerPage,
  handledblclick,
  printHeading,
  header,
  showFotter = false,
  totalQtyFoot,
  totalAmountFoot,
  disablePrint = false,
  disableCSV = false,
  selectedRecord = null,
  hideTimeCsv = false,
  showTime = false,
  hideGridOperations = false,
  allowRowSelect = true,
  customClass = "",
  showStore = false,
  showToolTipForReport = false,
  printHeadingSubject = "",
  totalModel = [],
  showTotalInCsv = false,
  IsCo2Report = false,  
  GridColumnToolTipAlignment = "left",
}) {
  const CandelaVersion = useGetTokenValue("CandelaVersion");
  const [selectedId, setSelectedId] = useState();
  const [tableData, setTableData] = useState(tablebody);
  const [showMailModal, setShowMailModal] = useState(false);
  const [toMail, setToMail] = useState("");
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");
  const [quantityPoint, setQuantityPoint] = useState(2);
  const [amountPoint, setAmountPoint] = useState(2);
  const [showStoreColumn, setShowStoreColumn] = useState(true);
  const tableRef = useRef(null);
  const apiUrl = import.meta.env.VITE_BACKEND_API_URL;
  const [isMobile, setIsMobile] = useState(false);
  const [showAdditionalColumn, setShowAdditionalColumn] = useState(false);

  // Check if device is mobile
  useEffect(() => {
    const checkMobile = () => {
      const isMobileDevice = window.innerWidth <= 768;
      setIsMobile(isMobileDevice);
    };

    checkMobile();
    window.addEventListener("resize", checkMobile);

    return () => {
      window.removeEventListener("resize", checkMobile);
    };
  }, []);

  useEffect(()=>{
if(tableData != null && tableData.length > 0){
if(typeof(setSelectedRecord) == "function"){
setSelectedId(tableData[0][id])
}
if(typeof(setSelectedRecord) == "function"){
setSelectedRecord(tableData[0])
}
}
},[tableData])

  let formattedDate = "";
  useEffect(() => {
    setTableData(tablebody);
    if(typeof(printHeading) == "object"){
      printHeading = printHeadingSubject;
    }


    setSubject(printHeading);
  }, [tablebody]);

  useEffect(() => {
    fetchConfigurationValues();
  }, []);

  useEffect(() => {
     if (showStore) {
      setShowStoreColumn(true);
    }else if (CandelaVersion == "1") {
      setShowStoreColumn(false);
    } else {
      if (localStorage.ShopId != "0") {
        setShowStoreColumn(false);
      }
    }
  }, [CandelaVersion,showStore]);

  const fetchConfigurationValues = async () => {
    let qtyConfig = await getTableDataByKey(
      "rcmsConfiguration",
      "configurationName",
      "DecimalPointInQty"
    );
    setQuantityPoint(qtyConfig.configurationValue);
    let amountConfig = await getTableDataByKey(
      "rcmsConfiguration",
      "configurationName",
      "DecimalPointInValue"
    );
    setAmountPoint(amountConfig.configurationValue);
  };

  useEffect(() => {
    if (selectedRecord == null) {
      setSelectedId(null);
    } else {
      setSelectedId(selectedRecord[id]);
    }
  }, [selectedRecord]);

  const handleRowSelect = (item) => {
    if (allowRowSelect) {
      setSelectedId(item[id]);
      setSelectedRecord(item);
    } else {
      setSelectedId(null);
      setSelectedRecord(null);
    }
  };
   // Helper function to build total row for CSV
   const buildTotalRowForCSV = (filteredGridModel) => {
    return filteredGridModel.map((col, index) => {
      if (index === 0) {
        return `"Total:"`;
      }
      
      if (totalModel.length > 0) {
        const totalEntry = totalModel.find((total) => total.name === col.name);
        if (totalEntry?.value != null) {
          return `"${thousandformater(totalEntry.value, amountPoint)}"`;
        }
      } else {
        const colName = col.name.toLowerCase();
        if (colName.includes("qty") || colName === "quantity") {
          return `"${thousandformater(totalQtyFoot, quantityPoint)}"`;
        } else if (
          colName.includes("amount") ||
          colName.includes("value") ||
          colName.includes("net sale")
        ) {
          return `"${thousandformater(totalAmountFoot, amountPoint)}"`;
        }
      }
      
      return `""`;
    });
  };
  const handleDownloadCSV = () => {
    if (!tableData || tableData.length === 0) {
      toast.error("No data in grid to export");
      return;
    }

    // Helper function to extract text from JSX or return the value as-is
    const getCSVValue = (value) => {
      // If it's a React element (JSX), extract the text content
      if (value && typeof value === "object" && value.props) {
        return extractTextFromJSX(value);
      }
      // Return the value as-is for other types
      return value || "";
    };

    // Helper function to recursively extract text from JSX
    const extractTextFromJSX = (jsxElement) => {
      try {
        if (typeof jsxElement === "string" || typeof jsxElement === "number") {
          return jsxElement;
        }

        if (!jsxElement || !jsxElement.props) {
          return "";
        }

        const { children } = jsxElement.props;

        if (!children) {
          return "";
        }

        if (Array.isArray(children)) {
          return children
            .map((child) => extractTextFromJSX(child))
            .filter(Boolean)
            .join(" ");
        }

        return extractTextFromJSX(children);
      } catch (error) {
        console.log(error);
        return "";
      }
    };

    //Remove Grid Model
    gridModel = gridModel.filter(
      (item) => !item.csvHeader.toLowerCase().includes("removefromcsv")
    );

    // Step 1: Build headers
    let headers = gridModel.map((col) => col.csvHeader);
    if (!showStoreColumn) {
      headers = headers.filter(
        (item) =>
          !(
            item.toLowerCase().includes("store") ||
            item.toLowerCase().includes("shop")
          )
      );
    }

    // Step 2: Build rows
    const rows = tableData.map((item) => {
      if (!showStoreColumn) {
        return gridModel
          .filter(
            (col) =>
              !col.name.toLowerCase().includes("shop") &&
              !col.name.toLowerCase().includes("store")
          )
          .map((col) => {
            const key = col.name.replace(/\s/g, "");
            let value = item[key];
            // Format date
            if (col.columnType.toLowerCase() === "date") {
              value = /^\d{1,2}\/[A-Za-z]{3}\/\d{4}$/.test(value)
                ? value
                : parseDate(value);
              // Hide time in CSV if hideTimeCsv is true
              if (hideTimeCsv && value.includes(" ")) {
                value = value.split(" ")[0];
              }
            }

            // Handle JSX elements
            value = getCSVValue(value);

            return `"${value}"`;
          });
      } else {
        return gridModel.map((col) => {
          const key = col.name.replace(/\s/g, "");
          let value = item[key];
          // Format date
          if (col.columnType.toLowerCase() === "date") {
            value = /^\d{1,2}\/[A-Za-z]{3}\/\d{4}$/.test(value)
              ? value
              : parseDate(value);
            // Hide time in CSV if hideTimeCsv is true
            if (hideTimeCsv && value.includes(" ")) {
              value = value.split(" ")[0];
            }
          }

          // Handle JSX elements
          value = getCSVValue(value);

          return `"${value}"`;
        });
      }
    });
// Step 3: Add total row if showtotalincsv is true and footer should be shown
if (showTotalInCsv && showFotter && tableData.length > 0) {
  const totalRow = buildTotalRowForCSV(gridModel);
  rows.push(totalRow);
}
    // Step 3: Combine header + rows into CSV string
    const csvContent =
      headers.join(",") + "\n" + rows.map((r) => r.join(",")).join("\n");

    // Step 4: Trigger download
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${csvName}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadPDF = () => {
    if(typeof(printHeading) == "object"){
      printHeading = printHeadingSubject;
      }
    if (!tableData || tableData.length === 0) {
      toast.error("No Data in Grid to Print!");
      return;
    }
    if(!IsCo2Report) {
      window.print();
    } else {
      const extractTextFromHTML = (value) => {
        if (value == null) return "";
        
        // If it's a React element or HTML object
        if (typeof value === 'object' && value.props) {
          // Try to extract text from props.children
          if (value.props.children) {
            if (typeof value.props.children === 'string') {
              return value.props.children + ' ';
            }
            if (typeof value.props.children === 'number') {
              return String(value.props.children) + ' ';
            }
            if (Array.isArray(value.props.children)) {
              return value.props.children.map(child => 
                typeof child === 'string' ? child + ' ' : 
                typeof child === 'number' ? String(child) + ' ' :
                extractTextFromHTML(child)
              ).join('');
            }
            if (typeof value.props.children === 'object') {
              return extractTextFromHTML(value.props.children);
            }
          }
          // If no children, try other common props
          const propValue = value.props.title || value.props.alt || value.props.value || '';
          return propValue ? propValue + ' ' : '';
        }
        
        // If it's already a string
        if (typeof value === 'string') {
          return value + ' ';
        }
        
        // If it's a number
        if (typeof value === 'number') {
          return String(value) + ' ';
        }
        
        // For other objects, try to convert to string
        const stringValue = String(value);
        return stringValue !== '[object Object]' ? stringValue + ' ' : '';
      };
  
      const createPrintableHTML = () => {        
        let html = `
          <div style="padding: 20px; font-family: Arial, sans-serif;">
            <h2 style="text-align: center; margin-bottom: 30px; font-size: 18px; font-weight: bold;">
              ${printHeading || 'C-02 Salesperson Report'}
            </h2>
            <table style="width: 100%; border-collapse: collapse; font-size: 12px;">
              <thead>
                <tr style="background-color: #3498db; color: white;">
        `;
  
        // Add headers using the existing visibleHeaders array
        visibleHeaders.forEach(header => {
          if (!showStore) {
            if (!showStoreColumn && (header.name.toLowerCase().includes("shop") || header.name.toLowerCase().includes("store"))) {
              return;
            }
            if ((header.name.toLowerCase().includes("shop") || header.name.toLowerCase().includes("store")) && localStorage.ShopId != "0") {
              return;
            }
          }
          
          const textAlign = header.columnType.toLowerCase() === "string" ? "left" : "right";
          html += `<th style="border: 1px solid #2980b9; padding: 8px; text-align: ${textAlign};">${header.name}</th>`;
        });
  
        html += `
                </tr>
              </thead>
              <tbody>
        `;
  
        // Add data rows using the existing visibleGridModel array
        tableData.forEach(item => {
          html += '<tr>';
          visibleGridModel.forEach(obj => {
            if (!showStore) {
              if (!showStoreColumn && (obj.name.toLowerCase().includes("shop") || obj.name.toLowerCase().includes("store"))) {
                return;
              }
              if ((obj.name.toLowerCase().includes("shop") || obj.name.toLowerCase().includes("store")) && localStorage.ShopId != "0") {
                return;
              }
            }
  
            const key = obj.name.replace(/\s/g, "");
            const textAlign = obj.columnType.toLowerCase() === "string" || obj.columnType.toLowerCase() === "boolean" ? "left" : "right";
            
            let cellValue = "";
            const rawValue = item[key];
            
            // Handle different column types exactly like the original grid
            if (obj.columnType.toLowerCase() === "numeric") {
              cellValue = rawValue != null ? String(rawValue) : "";
            } else if (obj.columnType.toLowerCase() === "date") {
              if (rawValue) {
                const dateValue = extractTextFromHTML(rawValue);
                cellValue = showTime ? dateValue : dateValue.split(" ")[0];
              } else {
                cellValue = "";
              }
            } else if (obj.columnType.toLowerCase() === "quantity") {
              cellValue = rawValue != null ? thousandformater(rawValue, quantityPoint) : "";
            } else if (obj.columnType.toLowerCase() === "value") {
              cellValue = rawValue != null ? thousandformater(rawValue, amountPoint) : "";
            } else if (obj.columnType.toLowerCase() === "boolean") {
              cellValue = rawValue === true ? String(rawValue) : "";
            } else {
              // For string and other types, extract text from HTML objects
              cellValue = extractTextFromHTML(rawValue);
            }
  
            html += `<td style="border: 1px solid #dee2e6; padding: 6px 8px; text-align: ${textAlign};">${cellValue}</td>`;
          });
          html += '</tr>';
        });
  
        // Add total row if exists
        if (totalModel && totalModel.length > 0 && showFotter) {
          html += '<tr style="background-color: #f8f9fa; font-weight: bold;">';
          let isFirstColumn = true;
          
          visibleGridModel.forEach((obj) => {
            if (!showStore) {
              if (!showStoreColumn && (obj.name.toLowerCase().includes("shop") || obj.name.toLowerCase().includes("store"))) {
                return;
              }
              if ((obj.name.toLowerCase().includes("shop") || obj.name.toLowerCase().includes("store")) && localStorage.ShopId != "0") {
                return;
              }
            }
  
            if (isFirstColumn) {
              html += '<td style="border: 1px solid #dee2e6; padding: 6px 8px; font-weight: bold;">Total:</td>';
              isFirstColumn = false;
            } else {
              const correspondingGridModel = gridModel.find(gm => gm.csvHeader === obj.name || gm.name === obj.name.replace(/\s/g, ""));
              if (correspondingGridModel) {
                const totalEntry = totalModel.find(total => total.name === correspondingGridModel.name);
                if (totalEntry?.value != null) {
                  const textAlign = obj.columnType.toLowerCase() === "string" || obj.columnType.toLowerCase() === "boolean" ? "left" : "right";
                  html += `<td style="border: 1px solid #dee2e6; padding: 6px 8px; text-align: ${textAlign}; font-weight: bold;">${thousandformater(totalEntry.value, amountPoint)}</td>`;
                } else {
                  html += '<td style="border: 1px solid #dee2e6; padding: 6px 8px;"></td>';
                }
              } else {
                html += '<td style="border: 1px solid #dee2e6; padding: 6px 8px;"></td>';
              }
            }
          });
          html += '</tr>';
        }
  
        html += `
              </tbody>
            </table>
          </div>
        `;
  
        return html;
      };
  
      // Use printJS with the clean HTML
      printJS({
        printable: createPrintableHTML(),
        type: 'raw-html',
        targetStyles: ['*'],
        documentTitle: 'C-02 Salesperson Report'
      });
    }
  };
  const sendEmail = async () => {
    if (!tableRef.current) {
      toast.error("Table not found");
      return false;
    }

    if (toMail == null || toMail == "") {
      toast.error("Please enter an Email ID.");
      return false;
    } else {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(toMail)) {
        toast.error("Please enter a Valid Email ID.");
        return false;
      }
    }
    if (subject == null || subject == "") {
      toast.error("Please enter subject.");
      return false;
    }

    try {
      // Configure html2canvas options for better quality
      const canvas = await html2canvas(tableRef.current, {
        scale: 2, // Higher scale for better quality
        useCORS: true,
        allowTaint: true,
        backgroundColor: "#ffffff",
        scrollX: 0,
        scrollY: 0,
      });

      let el = document.querySelector(".hide-print");
      if (el) el.style.display = "none";
      // Convert canvas to blob
      canvas.toBlob(
        (blob) => {
          if (blob) {
            const formData = new FormData();
            formData.append("Attachment", blob, `${printHeading}.png`);
            formData.append("EmailBody", body);
            formData.append("EmailTo", toMail);
            formData.append("EmailSubject", subject);

            apiService({
              endpoint: apiUrl + "/Email/Send",
              method: "POST",
              data: formData,
              contentType: "multipart/form-data",
            })
              .then((res) => {
                if (res.data.success) {
                  setShowMailModal(false);
                  toast.success("Mail sent successfully");
                } else {
                  setShowMailModal(false);
                  toast(res.error);
                }
              })
              .catch((ex) => {
                setShowMailModal(false);
                console.log(ex);
                toast.error("Something went wrong");
              });
          } else {
            setShowMailModal(false);
            toast.error("Failed to create image");
          }
        },
        "image/png",
        0.95
      );
      el = document.querySelector(".hide-print");
      if (el) el.style.display = "";
    } catch (error) {
      console.error("Error converting table to image:", error);
      toast.error("Failed to convert table to image");
    }
  };

  const convertTableToImage = async () => {
    const now = new Date();

    const day = now.getDate();
    const month = now.getMonth() + 1;
    const year = now.getFullYear();

    let hours = now.getHours();
    const minutes = now.getMinutes().toString().padStart(2, "0");
    const seconds = now.getSeconds().toString().padStart(2, "0");

    const ampm = hours >= 12 ? "PM" : "AM";
    hours = hours % 12;
    hours = hours ? hours : 12;
    if(typeof(printHeading) == "object"){
      printHeading = printHeadingSubject;
    }
    setBody(
      `${printHeading} as on ${day}/${month}/${year} ${hours}:${minutes}:${seconds} ${ampm}`
    );
    if (!tableData || tableData.length === 0) {
      toast.error("No data in grid to email!");
      return false;
    } else {
      setShowMailModal(true);
    }
  };

  //  Filter visible columns based on showHideType
  const visibleHeaders = header.filter(
    (col) => !col.showHideType || showAdditionalColumn
  );
  const visibleGridModel = gridModel.filter(
    (col) => !col.showHideType || showAdditionalColumn
  );

  const renderTableRows = () => {
    const currentRows = tableData.slice(0, 0 + rowsPerPage);
    {
      return currentRows.map((item, index) => {
        return (
          <tr
            className="tableRow"
            onDoubleClick={() => handledblclick(item)}
            onClick={() => handleRowSelect(item)}
            key={index}
          >
            {visibleGridModel.map((obj) => {
              const key = obj.name.replace(/\s/g, "");

              if (obj.columnType.toLowerCase() == "date") {
                formattedDate = /^\d{1,2}\/[A-Za-z]{3}\/\d{4}$/.test(item[key])
                  ? item[key]
                  : parseDate(item[key]);
                item[key] = formattedDate;
              }
              if (!showStore) {
              if (
                !showStoreColumn &&
                (key.toLowerCase().includes("shop") ||
                  key.toLowerCase().includes("store"))
              ) {
                return null;
              }
              if (
                (key.toLowerCase().includes("shop") ||
                  key.toLowerCase().includes("store")) &&
                localStorage.ShopId != "0"
              ) {
                return null;
              }
            }
              return (
                <td
                  key={key}
                  style={{
                    textAlign:
                      obj.columnType.toLowerCase() == "string" ||
                      obj.columnType.toLowerCase() == "boolean"
                        ? `left`
                        : `right`,
                    backgroundColor: selectedId == item[id] ? "#4FABFF" : "",
                    color: selectedId == item[id] ? "white" : "black",
                  }}
                  className={`${obj.hideInPrint == true ? "hide-print" : ""} recordGridRow`}
                >
                  {obj.columnType.toLowerCase() == "numeric"
                    ? item[key]
                    : obj.columnType.toLowerCase() == "date"
                    ? showTime
                      ? item[key]
                      : item[key].split(" ")[0]
                    : obj.columnType.toLowerCase() == "quantity"
                    ? thousandformater(item[key], quantityPoint)
                    : obj.columnType.toLowerCase() == "value"
                    ? thousandformater(item[key], amountPoint)
                    : obj.columnType.toLowerCase() == "boolean"
                    ? item[key] == true
                      ? item[key].toString()
                      : ""
                    : item[key]}
                </td>
              );
            })}
          </tr>
        );
      });
    }
  };
  return (
    <>
      <div className={`recordGridContainter ${customClass}`} id="printable-area">
        <h3 className="printHeading">{printHeading || ""}</h3>
        <div className="tableHeaderContainer" style={!printHeading && hideGridOperations? {display:"none"} : {}}>
          <span className="tablePrintHead ">{printHeading}</span>
          {!hideGridOperations && (
            <span className="printBtnContainer">
              <InfoIcon
                placement="top"
                body={
                  showToolTipForReport
                    ? "Note: Email, print or export will be done for the values displayed in the grid. If you need all data then use the download button above."
                    : `${
                        isMobile
                          ? "Note: Email will be done for the values displayed in the grid."
                          : "Note: Email, print or export will be done for the values displayed in the grid."
                      }`
                }
              />
              <motion.button
                whileTap={{
                  scale: "0.8",
                }}
                onClick={handleDownloadPDF}
                className={`gridPrintBtn mobileHideShow ${
                  disablePrint ? "disableBtn" : ""
                }`}
                disabled={disablePrint}
              >
                Print
              </motion.button>
              <motion.button
                whileTap={{
                  scale: "0.8",
                }}
                onClick={handleDownloadCSV}
                className={`gridPrintBtn mobileHideShow ${
                  disableCSV ? "disableBtn" : ""
                }`}
                disabled={disableCSV}
              >
                CSV
              </motion.button>
              <motion.button
                whileTap={{
                  scale: "0.8",
                }}
                onClick={convertTableToImage}
                className="gridPrintBtn"
              >
                Email
              </motion.button>
              {allowExpandCollapse && (
                  <motion.img
                    src="data:image/png;base64,"
                    alt=""
                    whileTap={{ scale: "0.8" }}
                    className="cPointer"
                    onClick={() =>
                      setShowAdditionalColumn(!showAdditionalColumn)
                    }
                    title="Show/Hide Additional Columns"
                  />
              )}
            </span>
          )}
           {hideGridOperations && allowExpandCollapse && (
                <motion.img
                  src="data:image/png;base64,"
                  alt=""
                  whileTap={{ scale: "0.8" }}
                  className="cPointer"
                  onClick={() =>
                    setShowAdditionalColumn(!showAdditionalColumn)
                  }
                  title="Show/Hide Additional Columns"
                />
           )}
        </div>
        <Table
          ref={tableRef}
          bordered
          responsive
          striped
          className="gridContainer"
        >
          <thead>
            <tr>
              {visibleHeaders.map((item, index) => {
                if (!showStore) {
                if (
                  !showStoreColumn &&
                  (item.name.toLowerCase().includes("shop") ||
                    item.name.toLowerCase().includes("store"))
                ) {
                  return null;
                }
                if (
                  (item.name.toLowerCase().includes("shop") ||
                    item.name.toLowerCase().includes("store")) &&
                  localStorage.ShopId != "0"
                ) {
                  return null;
                }
              }
                return (
                  <th
                    key={index}
                    style={
                      item.columnType.toLowerCase() == "string"
                        ? { textAlign: `left` }
                        : { textAlign: `right` }
                    }
                    className={`gridTableHeader ${
                      item.hideInPrint == true ? "hide-print" : ""
                    }`}
                  >
                    {item.name}{" "}
                    {item.showInfoIcon != null && item.showInfoIcon == true ? (
                      <>
                        <CustomTooltip body={item.tooltipText}  placement={GridColumnToolTipAlignment}>
                          <BsInfoCircleFill
                            size={14}
                            className="gridHeaderInfoIcon"
                          />
                        </CustomTooltip>
                      </>
                    ) : null}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {tableData == null || tableData.length == 0 ? (
              <tr>
                <td
                  colSpan={
                    visibleHeaders.filter(
                      (item) =>
                        showStoreColumn ||
                        (!item.name.toLowerCase().includes("shop") &&
                          !item.name.toLowerCase().includes("store"))
                    ).length
                  }
                  className="noData"
                >
                  No data available!
                </td>
              </tr>
            ) : (
              <>{renderTableRows()}</>
            )}
          </tbody>
          {showFotter && tableData.length > 0 && (
            <tfoot
              className="total-section"
              style={{ width: "100%", height: "3rem" }}
            >
              <tr>
                {visibleHeaders.map((item, index) => {
                  if (!showStore) {
                  if (
                    !showStoreColumn &&
                    (item.name.toLowerCase().includes("shop") ||
                      item.name.toLowerCase().includes("store"))
                  ) {
                    return null;
                  }
                  if (
                    (item.name.toLowerCase().includes("shop") ||
                      item.name.toLowerCase().includes("store")) &&
                    localStorage.ShopId != "0"
                  ) {
                    return null;
                  }
                }
                  if (index == 0) {
                    return (
                      <td
                        key={localStorage.ShopId != "0" ? 1 : index}
                        className="footColor recordtotal"
                      >
                        Total:
                      </td>
                    );
                  } else {
                    if (totalModel.length > 0) {
                      const correspondingGridModel = gridModel.find(
                        (gm) => gm.csvHeader === item.name || gm.name === item.name.replace(/\s/g, "")
                      );
                      
                      if (correspondingGridModel) {
                        const totalEntry = totalModel.find((total) => total.name === correspondingGridModel.name);
                        
                        if (totalEntry?.value != null) {
                          const decimalPoints = totalEntry.decimalPoints ?? amountPoint;
                          return (
                            <td key={index} className="footColor recordAlignRight footText">
                              {thousandformater(totalEntry.value, decimalPoints)}
                            </td>
                          );
                        }
                      }
                    } else {
                      if (
                        item.name.toLowerCase().includes("qty") ||
                        item.name.toLowerCase() == "quantity"
                      ) {
                        return (
                          <td
                            key={index}
                            className="footColor recordAlignRight footText"
                          >
                            {thousandformater(totalQtyFoot, quantityPoint)}
                          </td>
                        );
                      } else if (
                        item.name.toLowerCase().includes("amount") ||
                        item.name.toLowerCase().includes("value") ||
                        item.name.toLowerCase().includes("net sale")
                      ) {
                        return (  
                          <td
                            key={index}
                            className="footColor recordAlignRight footText"
                          >
                            {thousandformater(totalAmountFoot, amountPoint)}
                          </td>
                        );
                      }
                    }
                    return <td key={index} className="footColor"></td>;
                  }
                })}
              </tr>
            </tfoot>
          )}
        </Table>
      </div>
      {showMailModal && (
        <MailPopup
          showMailModal={showMailModal}
          setShowMailModal={setShowMailModal}
          body={body}
          setBody={setBody}
          subject={subject}
          setSubject={setSubject}
          toMail={toMail}
          setToMail={setToMail}
          sendEmail={sendEmail}
        />
      )}
    </>
  );
}
const parseDate = (input) => {
  if (!input) return "";
  let date;
  // If input is already a Date
  if (input instanceof Date) {
    date = input;
  } else if (typeof input === "string") {
    date = new Date(input);
    if (!isValid(date)) {
      date = parse(input, "MM/dd/yyyy hh:mm:ss a", new Date());
    }
  }
  // Final validation
  if (!isValid(date)) return "";
  return format(date, "dd/MMM/yyyy hh:mm:ss a");
};
